"""Mutation fuzz: no crashes, ledger/pipeline invariants always hold."""
import sys, random, json
sys.path.insert(0, '/workspace/tmp')
from harness import *

seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
rnd = random.Random(seed)

ROUTES = {}
for a in ['demo.test', 'alt.test', 'x.test', 'a-b.test', '10.0.0.1', '[2001:db8::1]',
          'demo.test:8080', 'alt.test:8443', '[::1]', '0.0.0.0']:
    for s in ['http', 'https']:
        ROUTES[s + '://' + a] = 'rack-' + a.replace('.', '-').replace('[', '').replace(']', '').replace(':', '-')

METHODS = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS']
def rnd_value():
    pool = 'abZ09-._~!$&\'()*+,;=:@/?% \t'
    v = ''.join(rnd.choice(pool) for _ in range(rnd.randint(0, 8))).strip(' \t')
    return v or 'v'

def rnd_name():
    pool = 'abZ09-._~!$&\'()*+,;=:@/?%'
    return ''.join(rnd.choice(pool) for _ in range(rnd.randint(0, 8)))

def rnd_authority():
    return rnd.choice(['demo.test', 'DEMO.TEST', 'alt.test', 'alt.test:8443',
                       'demo.test:8080', '10.0.0.1', '[2001:db8::1]', '[::1]',
                       'demo.test.', '_bad.test', 'bad-.test', '1.2.3.04', '[fe80::1%e]',
                       'demo..test', '', 'demo.test:0', 'x'*64 + '.com', 'demo.test:99999',
                       'bad test', 'demo.test:80:90', 'us\xe9.test'])

def rnd_path():
    return rnd.choice(['/', '/a', '/a%2Fb?x=1&x=2', '*', '//', '/a b', '/a#f', '', '/a\\b',
                       '/%' , '/a%zz', '/a/%41/b?q=%2f', '/a//b', '/x' * 20])

def rnd_fields():
    method = rnd.choice(METHODS + ['TRACE', 'CONNECT', 'get', 'MKCOL'])
    scheme = rnd.choice(['http', 'https', 'ftp', 'HTTP'])
    authority = rnd_authority()
    path = rnd_path()
    f = [[:x for x in (':method', method)], [':scheme', scheme], [':path', path]]
    auth_entry = rnd.choice([[':authority', authority], ['host', authority], None,
                             [':authority', authority], ['host', authority]])
    if auth_entry:
        f.append(auth_entry)
        if rnd.random() < 0.1:
            f.append(['host' if auth_entry[0] == ':authority' else ':authority', authority])
    for _ in range(rnd.randint(0, 6)):
        f.append([rnd_name(), rnd_value()])
    if rnd.random() < 0.3:
        f.append(['content-length', rnd.choice(['0', '2', '2, 2', '3', '', '02', 'x'])])
    if rnd.random() < 0.3:
        f.append(['cookie', rnd_value()])
    if rnd.random() < 0.2:
        f.append(['cookie', rnd_value()])
    if rnd.random() < 0.25:
        f.append(['te', rnd.choice(['trailers', 'identity', 'Trailers', ''])])
    if rnd.random() < 0.15:
        f.append([rnd.choice(['connection', 'keep-alive', 'transfer-encoding', 'upgrade',
                              'trailer', 'http2-settings', 'proxy-connection']), 'x'])
    rnd.shuffle(f) if rnd.random() < 0.35 else None
    return f

def make_events():
    events = []
    used = set()
    for i in range(rnd.randint(1, 40)):
        sid = rnd.choice(range(0, 40, 4))
        used.add(sid)
        op = rnd.random()
        if op < 0.4:
            events.append({'sid': sid, 'type': 'headers', 'fields': rnd_fields()})
        elif op < 0.6:
            n = rnd.randint(0, 400)
            events.append({'sid': sid, 'type': 'data',
                           'hex': bytes(rnd.randrange(256) for _ in range(n)).hex()})
        elif op < 0.7:
            events.append({'sid': sid, 'type': 'unknown',
                           'frame_type': rnd.choice([0, 1, 3, 4, 5, 7, 13, 33, 2**62 - 1]),
                           'hex': bytes(rnd.randrange(256) for _ in range(rnd.randint(0, 20))).hex()})
        elif op < 0.85:
            events.append({'sid': sid, 'type': 'headers',
                           'fields': [[rnd.choice(['x-audit-t', 'x-audit', 'x-audit-a.b', ':method',
                                                   'cookie', 'X-Debug']), rnd_value()]
                                      for _ in range(rnd.randint(0, 3))]})
        elif op < 0.93:
            events.append({'sid': sid, 'type': 'fin'})
        else:
            events.append({'sid': sid, 'type': 'reset'})
    return events, used

bad = 0
for trial in range(400):
    events, used = make_events()
    try:
        out = run({'routes': ROUTES, 'events': events})
    except Exception as exc:
        print('CRASH', trial, repr(exc))
        bad += 1
        continue
    sids = [s['sid'] for s in out['streams']]
    if sids != sorted(sids):
        print('UNSORTED', trial); bad += 1
    if set(sids) != used:
        print('SID SET', trial, sorted(used - set(sids)), sorted(set(sids) - used)); bad += 1
    for s in out['streams']:
        keys = set(s)
        if keys != {'sid','status','commit_at','origin','offset','length','cache_key'}:
            print('KEYS', trial, s); bad += 1
        if s['status'] == 'forwarded':
            if not isinstance(s['offset'], int) or s['length'] <= 0:
                print('BAD FWD', trial, s); bad += 1
            if s['cache_key'][0] not in METHODS:
                print('BAD METHOD', trial, s); bad += 1
            if s['cache_key'][1] not in ('http', 'https'):
                print('BAD SCHEME', trial, s); bad += 1
        else:
            if (s['commit_at'], s['origin'], s['offset'], s['cache_key']) != (None, None, None, None) \
               or s['length'] != 0:
                print('BAD BLANK', trial, s); bad += 1
    total = 0
    for label, hx in out['origins'].items():
        raw = bytes.fromhex(hx)
        total += len(raw)
        try:
            recs = parse_pipeline(raw)
        except Exception as exc:
            print('PARSE', trial, label, repr(exc)); bad += 1; continue
        pos = 0
        for r in recs:
            if r['offset'] != pos:
                print('OFFSETS', trial); bad += 1
            pos += r['length']
    if sum(s['length'] for s in out['streams'] if s['status'] == 'forwarded') != total:
        print('TOTAL', trial); bad += 1
assert bad == 0, bad
print('ok   fuzz seed', seed, '400 scenarios, invariants hold')
PYEOF
cd /workspace && for s in 1 2 3; do python3 tmp/t6.py $s 2>&1 | tail -6; done
